public static bool IsMirror (int[]arr)
{
// מונה שסופר את כמות הזוגות
int count = 0;

// לולאה שרצה על המערך
for (int i = 0; i < arr.Length; i++)
{
// לולאה שרצה על k ומשווה בין הערכים
for (int k = 0; k < arr.Length; k++)
{
// משווה האם המספר הנגדי נמצא
if ((-arr[i]) == arr[k])
{
// נמצא המספר הנגדי
count ++;
}
}
}
// אם מספר המונה שווה למספר המערך
if (count == arr.Length)
{
return true; // שווה
}
else
{
return false; // לא שווה
}

