public static int[] DiceStatistics(int[]arr)
{
// 21 יצירת מערך חדש בגודל
int[] newArr = new int[21];
// arr לולאה שרצה על המערך
for(int i = 0; i<arr.Length; i++)
{
// newArr לולאה שרצה על המערך
for(int k = 1; k<newArr; k++)
{
// kל שווה arr אם המיקום i במערך
if(arr[i]==k)
{
// מוסיף אחד אם נמצא
newArr[k]++;
}
}
}
return newArr;
}

